<?php
$heroImages = db()->query('SELECT id,titre,texte_alternatif,chemin_fichier FROM images_hero WHERE actif=1 ORDER BY position,id')->fetchAll();
$heroSlides = array_map(static fn($image) => ['src'=>'?page=visual&kind=hero&id='.(int)$image['id'].'&v='.substr($image['chemin_fichier'],0,8),'title'=>$image['titre'],'alt'=>$image['texte_alternatif']], $heroImages);
$latest = db()->query("SELECT t.*, (SELECT p.id FROM photos_terrains p WHERE p.terrain_id=t.id AND p.type='photo' ORDER BY p.id LIMIT 1) AS photo_id, (SELECT AVG(a.note) FROM avis_terrains a WHERE a.terrain_id=t.id AND a.statut='publie') AS rating_avg, (SELECT COUNT(*) FROM avis_terrains a WHERE a.terrain_id=t.id AND a.statut='publie') AS rating_count FROM terrains t WHERE t.statut='disponible' ORDER BY t.date_publication DESC LIMIT 8")->fetchAll();
$projects = db()->query("SELECT r.*,AVG(a.note) AS rating_avg,COUNT(a.id) AS rating_count FROM realisations r LEFT JOIN avis_terrains a ON a.realisation_id=r.id AND a.statut='publie' WHERE r.actif=1 GROUP BY r.id ORDER BY r.date_creation DESC LIMIT 8")->fetchAll();
$stats = db()->query("SELECT COUNT(*) AS count FROM terrains WHERE statut='disponible'")->fetch();
$heroStyle = $heroSlides ? 'background-image:linear-gradient(180deg,#071d2410 44%,#071d24b8),url("'.$heroSlides[0]['src'].'")' : '';
?>
